head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[dataMap > M > modifyKeyStatus]<br/>Key 의 ID 를 사용하여 특정 Key 의 '변경여부' 상태값을 변경합니다.",
    "validation" : [        
        "keyId(필수) 파라미터로 '변경여부' 상태값을 변경하려는 Key 의 ID 를 설정합니다.",
        "status(필수) 파라미터로 Key 의 '변경여부' 상태값을 true/false 로 설정합니다.",
		"status(필수) 파라미터로 true 설정 시 Key 의 '변경여부' 상태를 '변경됨' 으로 설정합니다.",
		"status(필수) 파라미터로 false 설정 시 Key 의 '변경여부' 상태를 '변경없음' 으로 설정합니다.",
		"값(Value)이 변경된 Key 의 '변경여부' 상태값을 false 로 변경한 경우 getModified 계열의 메소드 반환값에서 제외됩니다. 단, getOriginal() 메소드의 반환값은 '변경여부' 상태값과 관계없이 원본값(Origin Value)을 반환합니다.",
    ]
}



scwin.onpageload = function () {
    // Global DataList 생성 호출
    $c.gcm.createCommonDatalist();

    // comp 초기 생성
    scwin.comp_init();

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};



// comp 생성
scwin.comp_init = async function () {
    // 기존 target 있으면 삭제
    if (typeof target1 !== 'undefined') {
        $p.data.remove("target1");
    }    

    if (typeof input1 !== 'undefined') {
        input1.remove();
    }    

    // target 생성
    $c.gcm.createBasicDataMap();

    // input 생성
    $c.gcm.createEmptyInput('ref="data:target1.key1" style="width:200px;"', '', 'input1');

    scwin.btn_set_onclick();
    scwin.btn_getModifiedJSON_onclick();
}



scwin.btn_set_onclick = function (e) {
    target1.set("key1", "change1");
    target1.set("key2", "change2");
    target1.set("key3", "change3");
    target1.set("key4", "change4");
}



scwin.btn_getOriginal_onclick = function (e) {
    let keyId = par_keyId.getText();
    let rtn = "";

    rtn = target1.getOriginal(keyId);

    wf_body_bottom.getObj("scwin").setReturnValue("getOriginal : " + rtn);  
};



scwin.btn_getModifiedJSON_onclick = function (e) {
    let rtn = target1.getModifiedJSON();
    let jsonString = JSON.stringify(rtn);

    wf_body_bottom.getObj("scwin").setReturnValue("getModifiedJSON : " + jsonString);  
}



scwin.btn_modifyKeyStatus_onclick = function (e) {
    let keyId = par_keyId.getText();
    let status = par_status.getText();

    target1.modifyKeyStatus(keyId, status);

    scwin.btn_getModifiedJSON_onclick();
    scwin.btn_getOriginal_onclick();
};
